			{
				ShowMeterData(response);
				IsConnected = true;
			}
			else
			{
				IsConnected = false;
			}
			Thread.Sleep(20);
			timer1.Enabled = false;
			Modbus.sp.DiscardOutBuffer();
			Modbus.sp.DiscardInBuffer();
			byte[] array = new byte[8];
			byte[] response2 = new byte[45];
			byte[] CRC = new byte[2];
			array[0] = Convert.ToByte(Parameters.Address);
			array[1] = 3;
			array[2] = 97;
			array[3] = 80;
			array[4] = 0;
			array[5] = 20;
			m.GetCRC(array, ref CRC);
			m.GetCRC(array, ref CRC);
			array[^2] = CRC[0];
			array[^1] = CRC[1];
			try
			{
				Modbus.sp.Write(array, 0, array.Length);
				PortFlashWrite();
				Thread.Sleep(20);
				m.GetResponse(ref response2);
				PortFlashRead();
			}
			catch (Exception ex2)
			{
				timer1.Enabled = false;
				IsConnected = false;
				PortFalshInit();
				MessageBox.Show(ex2.Message);
				MessageBox.Show(" Please confirm the serial port and address settings");
				return;
			}
			if (m.CheckResponse(response2))
			{
				if (Parameters.IsUse485)
				{
					timer1.Enabled = true;
				}
				if (response2[3] >= 8)
				{
					联网检验ovalShape1.FillColor = Color.Green;
				}
				else
				{
					联网检验ovalShape1.FillColor = Color.Red;
				}
				string text = "";
				byte[] array2 = new byte[15];
				byte[] array3 = new byte[20];
				string text2 = "state：" + response2[3] + "\nSignal：" + response2[4];
				for (int i = 0; i < 15; i++)
				{
					array2[i] = response2[5 + i];
				}
				string text3 = "IMEI：" + Encoding.Default.GetString(array2);
				for (int j = 0; j < 20; j++)
				{
					array3[j] = response2[20 + j];
				}
				text = "ICCID：" + Encoding.Default.GetString(array3);
				((Control)联网状态).Text = text2 + "\n" + text3 + "\n" + text;
				IsConnected = true;
			}
			Thread.Sleep(20);
			if (!CheckAddr())
			{
				return;
			}
			timer1.Enabled = false;
			Modbus.sp.DiscardOutBuffer();
			Modbus.sp.DiscardInBuffer();
			byte[] array4 = new byte[8];
			byte[] response3 = new byte[7];
			byte[] CRC2 = new byte[2];
			array4[0] = Convert.ToByte(Parameters.Address);
			array4[1] = 3;
			array4[2] = 1;
			array4[3] = 193;
			array4[4] = 0;
			array4[5] = 1;
			m.GetCRC(array4, ref CRC2);
			m.GetCRC(array4, ref CRC2);
			array4[^2] = CRC2[0];
			array4[^1] = CRC2[1];
			try
			{
				Modbus.sp.Write(array4, 0, array4.Length);
				PortFlashWrite();
				Thread.Sleep(20);
				m.GetResponse(ref response3);
				PortFlashRead();
			}
			catch (Exception ex3)
			{
				timer1.Enabled = false;
				IsConnected = false;
				PortFalshInit();
				MessageBox.Show(ex3.Message);
				MessageBox.Show(" Please confirm the serial port and address settings");
				return;
			}
			double num = 0.0;
			if (m.CheckResponse(response3))
			{
				if (Parameters.IsUse485)
				{
					timer1.Enabled = true;
				}
				num = (int)(ushort)((response3[3] << 8) | response3[4]);
				num = Convert.ToDouble(num) / 1000.0;
				((Control)textBoxIa).Text = Ia.ToString("f3");
				((Control)漏电流值).Text = num.ToString();
				IsConnected = true;
			}
		}
