	private int CheckAddrToSet()
	{
		int num = 0;
		int num2 = 0;
		if (((Control)textBoxAddrToSet).Text.Trim() == "")
		{
			return 3;
		}
		string text = ((Control)textBoxAddrToSet).Text.Trim();
		foreach (char c in text)
		{
			if (c < '0' || c > '9')
			{
				num++;
			}
		}
		if (num > 0)
		{
			return 1;
		}
		num = Convert.ToInt16(((Control)textBoxAddrToSet).Text.Trim());
		if (num > 247 || num <= 0)
		{
			return 2;
		}
		return 0;
	}

