	private void buttonReadSched1_Click(object sender, EventArgs e)
	{
		//IL_00b1: Unknown result type (might be due to invalid IL or missing references)
		//IL_00bc: Unknown result type (might be due to invalid IL or missing references)
		//IL_0115: Unknown result type (might be due to invalid IL or missing references)
		//IL_0106: Unknown result type (might be due to invalid IL or missing references)
		if (!CheckAddr())
		{
			return;
		}
		timer1.Enabled = false;
		Modbus.sp.DiscardOutBuffer();
		Modbus.sp.DiscardInBuffer();
		byte[] smessage = new byte[8];
		byte[] response = new byte[47];
		m.BuildSetMessage(34, ref smessage);
		try
		{
			Modbus.sp.Write(smessage, 0, smessage.Length);
			PortFlashWrite();
			Thread.Sleep(20);
			m.GetResponse(ref response);
			PortFlashRead();
		}
		catch (Exception ex)
		{
			timer1.Enabled = false;
			IsConnected = false;
			PortFalshInit();
			MessageBox.Show(ex.Message);
			MessageBox.Show(" Please confirm the serial port and address settings");
			return;
		}
		if (m.CheckResponse(response))
		{
			if (Parameters.IsUse485)
			{
				timer1.Enabled = true;
			}
			ShowTimeSchedu(response, 1);
			IsConnected = true;
			MessageBox.Show("Read successfully");
		}
		else
		{
			MessageBox.Show("No reply or checksum error");
		}
	}

