	private void buttonSetSched1_Click(object sender, EventArgs e)
	{
		//IL_012f: Unknown result type (might be due to invalid IL or missing references)
		//IL_013a: Unknown result type (might be due to invalid IL or missing references)
		//IL_002d: Unknown result type (might be due to invalid IL or missing references)
		//IL_0048: Unknown result type (might be due to invalid IL or missing references)
		//IL_0063: Unknown result type (might be due to invalid IL or missing references)
		//IL_007e: Unknown result type (might be due to invalid IL or missing references)
		//IL_018a: Unknown result type (might be due to invalid IL or missing references)
		//IL_017b: Unknown result type (might be due to invalid IL or missing references)
		int num = 0;
		if (!CheckAddr())
		{
			return;
		}
		switch (CheckTimeScheSet1())
		{
		case 2:
			MessageBox.Show("Please confirm that the input time table does not contain any other characters！");
			return;
		case 1:
			MessageBox.Show("Please confirm that the time table has been entered！");
			return;
		case 3:
			MessageBox.Show("Please confirm that the correct minutes have been entered！");
			return;
		case 4:
			MessageBox.Show("Please confirm that the correct time has been entered！");
			return;
		}
		GetTimeSche1();
		timer1.Enabled = false;
		Modbus.sp.DiscardOutBuffer();
		Modbus.sp.DiscardInBuffer();
		byte[] smessage = new byte[51];
		byte[] response = new byte[8];
		m.BuildSetMessage(35, ref smessage);
		try
		{
			Modbus.sp.Write(smessage, 0, smessage.Length);
			PortFlashWrite();
			Thread.Sleep(20);
			m.GetResponse(ref response);
			PortFlashRead();
		}
		catch (Exception ex)
		{
			timer1.Enabled = false;
			IsConnected = false;
			PortFalshInit();
			MessageBox.Show(ex.Message);
			MessageBox.Show(" Please confirm the serial port and address settings");
			return;
		}
		if (m.CheckResponse(response))
		{
			if (Parameters.IsUse485)
			{
				timer1.Enabled = true;
			}
			IsConnected = true;
			MessageBox.Show("Set successfully");
		}
		else
		{
			MessageBox.Show("No reply or checksum error");
		}
	}

