		{
		case 2:
			MessageBox.Show("Please confirm that the input time table does not contain any other characters！");
			return;
		case 1:
			MessageBox.Show("Please confirm that the time table has been entered！");
			return;
		case 3:
			MessageBox.Show("Please confirm that the correct minutes have been entered！");
			return;
		case 4:
			MessageBox.Show("Please confirm that the correct time has been entered！");
			return;
		}
		GetTimeSche2();
		timer1.Enabled = false;
		Modbus.sp.DiscardOutBuffer();
		Modbus.sp.DiscardInBuffer();
		byte[] smessage = new byte[51];
		byte[] response = new byte[8];
		m.BuildSetMessage(37, ref smessage);
		try
		{
			Modbus.sp.Write(smessage, 0, smessage.Length);
			PortFlashWrite();
			Thread.Sleep(20);
			m.GetResponse(ref response);
			PortFlashRead();
		}
		catch (Exception ex)
		{
			timer1.Enabled = false;
			IsConnected = false;
			PortFalshInit();
			MessageBox.Show(ex.Message);
