			return;
		}
		if (m.CheckResponse(response))
		{
			if (Parameters.IsUse485)
			{
				timer1.Enabled = true;
			}
			IsConnected = true;
			MessageBox.Show("Set successfully");
		}
		else
		{
			MessageBox.Show("No reply or checksum error");
		}
	}

