	private void GetMeterID()
	{
		string text = "";
		int num = 12 - ((Control)textBoxMeterID).Text.Length;
		for (int i = 0; i < num; i++)
		{
			text += "0";
		}
		((Control)textBoxMeterID).Text = text + ((Control)textBoxMeterID).Text;
		int num2 = 0;
		int num3 = 0;
		while (num2 < 6)
		{
			Parameters.MeterIDToSet[num3] = (byte)(Convert.ToInt16(((Control)textBoxMeterID).Text.Substring(num2 * 2, 2)) / 10 * 16 + Convert.ToInt16(((Control)textBoxMeterID).Text.Substring(num2 * 2, 2)) % 10);
			num2++;
			num3++;
		}
	}

