			{
				电压总谐波过高.Checked = true;
			}
			else
			{
				电压总谐波过高.Checked = false;
			}
			if ((response[3] & 2) == 2)
			{
				电流总谐波过高.Checked = true;
			}
			else
			{
				电流总谐波过高.Checked = false;
			}
			if ((response[3] & 4) == 4)
