	private void 读取当前需量_Click(object sender, EventArgs e)
	{
		//IL_00fe: Unknown result type (might be due to invalid IL or missing references)
		//IL_0109: Unknown result type (might be due to invalid IL or missing references)
		//IL_027c: Unknown result type (might be due to invalid IL or missing references)
		//IL_026d: Unknown result type (might be due to invalid IL or missing references)
		if (!CheckAddr())
		{
			return;
		}
		timer1.Enabled = false;
		Modbus.sp.DiscardOutBuffer();
		Modbus.sp.DiscardInBuffer();
		byte[] array = new byte[8];
		byte[] response = new byte[21];
		byte[] CRC = new byte[2];
		array[0] = Convert.ToByte(Parameters.Address);
		array[1] = 3;
		array[2] = 1;
		array[3] = 90;
		array[4] = 0;
		array[5] = 8;
		m.GetCRC(array, ref CRC);
		m.GetCRC(array, ref CRC);
		array[^2] = CRC[0];
		array[^1] = CRC[1];
		try
		{
			Modbus.sp.Write(array, 0, array.Length);
			PortFlashWrite();
			Thread.Sleep(20);
			m.GetResponse(ref response);
			PortFlashRead();
		}
		catch (Exception ex)
		{
			timer1.Enabled = false;
			IsConnected = false;
			PortFalshInit();
			MessageBox.Show(ex.Message);
			MessageBox.Show(" Please confirm the serial port and address settings");
			return;
		}
		if (m.CheckResponse(response))
		{
			if (Parameters.IsUse485)
			{
				timer1.Enabled = true;
			}
			int num = 0;
			num = (response[3] << 24) | (response[4] << 16) | (response[5] << 8) | response[6];
			((Control)当前正向有功需量).Text = (Convert.ToDouble(num) / 1000.0).ToString("f3");
			num = (response[7] << 24) | (response[8] << 16) | (response[9] << 8) | response[10];
			((Control)当前反向有功需量).Text = (Convert.ToDouble(num) / 1000.0).ToString("f3");
			num = (response[11] << 24) | (response[12] << 16) | (response[13] << 8) | response[14];
			((Control)当前正向无功需量).Text = (Convert.ToDouble(num) / 1000.0).ToString("f3");
			num = (response[15] << 24) | (response[16] << 16) | (response[17] << 8) | response[18];
			((Control)当前反向无功需量).Text = (Convert.ToDouble(num) / 1000.0).ToString("f3");
			IsConnected = true;
			MessageBox.Show("Read successfully");
		}
		else
		{
			MessageBox.Show("No reply or checksum error");
		}
	}

