			{
				DHCP_EIOT.Checked = false;
				((Control)IP_STA_1).Enabled = false;
				((Control)IP_STA_2).Enabled = false;
				((Control)IP_STA_3).Enabled = false;
				((Control)IP_STA_4).Enabled = false;
				((Control)GW1).Enabled = false;
				((Control)GW2).Enabled = false;
				((Control)GW3).Enabled = false;
