				((Control)NM2).Enabled = false;
				((Control)NM3).Enabled = false;
				((Control)NM4).Enabled = false;
			}
			((Control)IP_STA_1).Text = response[5].ToString();
			((Control)IP_STA_2).Text = response[6].ToString();
			((Control)IP_STA_3).Text = response[7].ToString();
			((Control)IP_STA_4).Text = response[8].ToString();
			((Control)GW1).Text = response[9].ToString();
